package com.fasterxml.jackson.core;

import com.fasterxml.jackson.core.sym.CharsToNameCanonicalizer;
import org.junit.Test;
import static org.junit.Assert.*;

public class JsonFactorySetStreamReadConstraintsTest {

    @Test
    public void testSetStreamReadConstraintsUpdatesMaxNameLengthInSymbolTable() {
        // Create factory with default constraints
        JsonFactory factory = new JsonFactory();
        int defaultMaxNameLength = factory.streamReadConstraints().getMaxNameLength();

        // Create new constraints with different maxNameLength
        StreamReadConstraints newConstraints = StreamReadConstraints.builder()
                .maxNameLength(defaultMaxNameLength + 1000)
                .build();

        // Apply new constraints - this should trigger recreation of rootCharSymbols
        factory.setStreamReadConstraints(newConstraints);

        // Verify the constraints were updated
        assertEquals(defaultMaxNameLength + 1000, factory.streamReadConstraints().getMaxNameLength());

        // The key test: verify that the symbol table uses the new maxNameLength
        // We need to access the internal rootCharSymbols to check its constraints
        // Since _rootCharSymbols is protected, we can use reflection or test through parsing
        // Let's test by parsing a long field name that would exceed old limit but be within new limit

        // Create a JSON with a field name that's longer than default but within new limit
        int testNameLength = defaultMaxNameLength + 500;
        StringBuilder sb = new StringBuilder();
        sb.append("{\"");
        for (int i = 0; i < testNameLength; i++) {
            sb.append("a");
        }
        sb.append("\":123}");
        String json = sb.toString();

        try {
            // This should succeed with the new constraints
            JsonParser parser = factory.createParser(json);
            parser.nextToken(); // Start object
            parser.nextToken(); // Field name
            String fieldName = parser.currentName();
            assertEquals(testNameLength, fieldName.length());
            parser.nextToken(); // Value
            assertEquals(JsonToken.VALUE_NUMBER_INT, parser.currentToken());
            assertEquals(123, parser.getIntValue());
            parser.nextToken(); // End object
            parser.close();
        } catch (Exception e) {
            fail("Should not throw exception with updated maxNameLength, but got: " + e);
        }
    }

    @Test
    public void testSetStreamReadConstraintsWithSameMaxNameLengthDoesNotRecreateSymbolTable() {
        JsonFactory factory = new JsonFactory();
        StreamReadConstraints originalConstraints = factory.streamReadConstraints();

        // Get the original rootCharSymbols reference
        CharsToNameCanonicalizer originalSymbols = getRootCharSymbols(factory);

        // Create new constraints with same maxNameLength but different other constraint
        StreamReadConstraints newConstraints = StreamReadConstraints.builder()
                .maxNameLength(originalConstraints.getMaxNameLength())
                .maxStringLength(originalConstraints.getMaxStringLength() + 1000)
                .build();

        // Apply new constraints
        factory.setStreamReadConstraints(newConstraints);

        // Get the new rootCharSymbols reference
        CharsToNameCanonicalizer newSymbols = getRootCharSymbols(factory);

        // With the patch: symbol table should NOT be recreated when maxNameLength doesn't change
        // So they should be the same object reference
        assertSame("Symbol table should not be recreated when maxNameLength doesn't change", 
                  originalSymbols, newSymbols);

        // Verify other constraint was updated
        assertEquals(originalConstraints.getMaxStringLength() + 1000, 
                    factory.streamReadConstraints().getMaxStringLength());
    }

    @Test
    public void testSetStreamReadConstraintsWithDifferentMaxNameLengthRecreatesSymbolTable() {
        JsonFactory factory = new JsonFactory();
        StreamReadConstraints originalConstraints = factory.streamReadConstraints();

        // Get the original rootCharSymbols reference
        CharsToNameCanonicalizer originalSymbols = getRootCharSymbols(factory);

        // Create new constraints with different maxNameLength
        StreamReadConstraints newConstraints = StreamReadConstraints.builder()
                .maxNameLength(originalConstraints.getMaxNameLength() + 1000)
                .build();

        // Apply new constraints
        factory.setStreamReadConstraints(newConstraints);

        // Get the new rootCharSymbols reference
        CharsToNameCanonicalizer newSymbols = getRootCharSymbols(factory);

        // With the patch: symbol table SHOULD be recreated when maxNameLength changes
        // So they should be different object references
        assertNotSame("Symbol table should be recreated when maxNameLength changes", 
                     originalSymbols, newSymbols);
    }

    @Test
    public void testSetStreamReadConstraintsNullThrowsException() {
        JsonFactory factory = new JsonFactory();
        try {
            factory.setStreamReadConstraints(null);
            fail("Should throw NullPointerException");
        } catch (NullPointerException e) {
            // Expected
        }
    }

    @Test
    public void testSetStreamReadConstraintsChaining() {
        JsonFactory factory = new JsonFactory();
        StreamReadConstraints newConstraints = StreamReadConstraints.builder()
                .maxNameLength(50000)
                .build();

        // Method should return this for chaining
        JsonFactory result = factory.setStreamReadConstraints(newConstraints);
        assertSame(factory, result);
    }

    // Helper method to access protected field using reflection
    private CharsToNameCanonicalizer getRootCharSymbols(JsonFactory factory) {
        try {
            java.lang.reflect.Field field = JsonFactory.class.getDeclaredField("_rootCharSymbols");
            field.setAccessible(true);
            return (CharsToNameCanonicalizer) field.get(factory);
        } catch (Exception e) {
            throw new RuntimeException("Failed to access _rootCharSymbols", e);
        }
    }
}

