package com.fasterxml.jackson.core;

import org.junit.Test;
import static org.junit.Assert.*;

public class JsonPointerAppendTailTest {

    @Test
    public void testAppendWithTailPointer() {
        // Original pointer with multiple segments
        JsonPointer original = JsonPointer.compile("/a1/b/c");

        // Get tail pointer (should represent "/b/c")
        JsonPointer tail = original.tail();

        // Create another pointer to append to
        JsonPointer other = JsonPointer.compile("/a2");

        // Append the tail pointer
        JsonPointer result = other.append(tail);

        // Expected: "/a2/b/c"
        // Buggy behavior before patch: "/a2/a1/b/c"
        JsonPointer expected = JsonPointer.compile("/a2/b/c");

        // Verify the result matches expected
        assertEquals("Appending tail pointer should produce correct concatenation", 
                     expected.toString(), result.toString());

        // Also verify the pointers are equal
        assertEquals(expected, result);
    }

    @Test
    public void testAppendWithTailPointerMultipleLevels() {
        // Test with deeper nesting
        JsonPointer original = JsonPointer.compile("/a/b/c/d/e");
        JsonPointer tail = original.tail(); // Should be "/b/c/d/e"
        JsonPointer other = JsonPointer.compile("/x/y");
        JsonPointer result = other.append(tail);

        JsonPointer expected = JsonPointer.compile("/x/y/b/c/d/e");
        assertEquals("Appending deep tail pointer should work correctly",
                     expected.toString(), result.toString());
        assertEquals(expected, result);
    }

    @Test
    public void testAppendWithEmptyPointer() {
        // Test edge case with empty pointer
        JsonPointer empty = JsonPointer.compile("");
        JsonPointer original = JsonPointer.compile("/a/b/c");
        JsonPointer tail = original.tail(); // "/b/c"

        // Append tail to empty pointer
        JsonPointer result = empty.append(tail);

        // Should just be the tail
        JsonPointer expected = JsonPointer.compile("/b/c");
        assertEquals("Appending tail to empty pointer should work",
                     expected.toString(), result.toString());
        assertEquals(expected, result);
    }

    @Test
    public void testAppendPropertyAfterFix() {
        // Verify appendProperty also works correctly with the new toStringBuilder
        JsonPointer ptr = JsonPointer.compile("/a/b");
        JsonPointer result = ptr.appendProperty("c");

        JsonPointer expected = JsonPointer.compile("/a/b/c");
        assertEquals("appendProperty should work correctly",
                     expected.toString(), result.toString());
        assertEquals(expected, result);
    }

    @Test
    public void testAppendIndexAfterFix() {
        // Verify appendIndex also works correctly
        JsonPointer ptr = JsonPointer.compile("/a/b");
        JsonPointer result = ptr.appendIndex(5);

        JsonPointer expected = JsonPointer.compile("/a/b/5");
        assertEquals("appendIndex should work correctly",
                     expected.toString(), result.toString());
        assertEquals(expected, result);
    }

    @Test
    public void testTailToStringRespectsOffset() {
        // Direct test of toString() behavior with offset
        JsonPointer original = JsonPointer.compile("/head/tail1/tail2");
        JsonPointer tail = original.tail();

        // toString() should return only the tail portion
        assertEquals("/tail1/tail2", tail.toString());

        // Verify the internal offset is set
        assertTrue("Tail pointer should have offset > 0", 
                   ((JsonPointer) tail)._asStringOffset > 0);
    }

    @Test
    public void testAppendChainWithTail() {
        // More complex scenario: chain of operations
        JsonPointer base = JsonPointer.compile("/base");
        JsonPointer original = JsonPointer.compile("/a/b/c/d");
        JsonPointer tail1 = original.tail(); // "/b/c/d"
        JsonPointer tail2 = tail1.tail();    // "/c/d"

        JsonPointer result = base.append(tail1).append(tail2);

        // Expected: /base/b/c/d/c/d
        // This tests multiple appends with tail pointers
        JsonPointer expected = JsonPointer.compile("/base/b/c/d/c/d");
        assertEquals("Chained appends with tail pointers should work",
                     expected.toString(), result.toString());
        assertEquals(expected, result);
    }
}

