package com.fasterxml.jackson.core;

import org.junit.Test;
import static org.junit.Assert.*;

public class JsonPointerAppendTailTest {

    @Test
    public void testAppendWithTailPointer() {
        // Original pointer with multiple segments
        JsonPointer original = JsonPointer.compile("/a1/b/c");

        // Get tail pointer (should be "/b/c")
        JsonPointer tail = original.tail();

        // Create another pointer and append the tail
        JsonPointer other = JsonPointer.compile("/a2");
        JsonPointer result = other.append(tail);

        // Expected: "/a2/b/c"
        // Buggy behavior before patch: "/a2/a1/b/c"
        JsonPointer expected = JsonPointer.compile("/a2/b/c");

        assertEquals("Appending tail pointer should not include original head", 
                     expected.toString(), result.toString());
        assertEquals("Compiled pointers should be equal", expected, result);
    }

    @Test
    public void testAppendWithTailPointerMultipleLevels() {
        // Test with deeper nesting
        JsonPointer original = JsonPointer.compile("/a/b/c/d/e");
        JsonPointer tail = original.tail(); // Should be "/b/c/d/e"

        JsonPointer other = JsonPointer.compile("/x/y");
        JsonPointer result = other.append(tail);

        JsonPointer expected = JsonPointer.compile("/x/y/b/c/d/e");

        assertEquals("Appending tail pointer with multiple levels", 
                     expected.toString(), result.toString());
        assertEquals(expected, result);
    }

    @Test
    public void testAppendWithTailOfTail() {
        // Chain of tail operations
        JsonPointer original = JsonPointer.compile("/a/b/c/d");
        JsonPointer tail1 = original.tail(); // "/b/c/d"
        JsonPointer tail2 = tail1.tail();    // "/c/d"

        JsonPointer other = JsonPointer.compile("/x");
        JsonPointer result = other.append(tail2);

        JsonPointer expected = JsonPointer.compile("/x/c/d");

        assertEquals("Appending tail of tail pointer", 
                     expected.toString(), result.toString());
        assertEquals(expected, result);
    }

    @Test
    public void testAppendWithEmptyPointer() {
        // Edge case: appending to empty pointer
        JsonPointer empty = JsonPointer.compile("");
        JsonPointer original = JsonPointer.compile("/a/b/c");
        JsonPointer tail = original.tail(); // "/b/c"

        JsonPointer result = empty.append(tail);

        // Empty pointer appending should just return the tail
        assertEquals("/b/c", result.toString());
        assertEquals(tail, result);
    }

    @Test
    public void testAppendTailToEmptyPointer() {
        // Edge case: appending empty pointer to tail
        JsonPointer original = JsonPointer.compile("/a/b");
        JsonPointer tail = original.tail(); // "/b"
        JsonPointer empty = JsonPointer.compile("");

        JsonPointer result = tail.append(empty);

        // Appending empty should return the original pointer
        assertEquals("/b", result.toString());
        assertEquals(tail, result);
    }

    @Test
    public void testToStringBuilderWithOffset() {
        // Test the new toStringBuilder method directly
        JsonPointer original = JsonPointer.compile("/a/b/c");
        JsonPointer tail = original.tail();

        // Use reflection to access protected method
        java.lang.reflect.Method toStringBuilderMethod = null;
        try {
            toStringBuilderMethod = JsonPointer.class.getDeclaredMethod("toStringBuilder", int.class);
            toStringBuilderMethod.setAccessible(true);

            StringBuilder sb = (StringBuilder) toStringBuilderMethod.invoke(tail, 5);

            // tail.toString() should be "/b/c"
            assertEquals("/b/c", sb.toString());

            // Verify the offset handling
            assertEquals(5, sb.capacity() - sb.length());
        } catch (Exception e) {
            fail("Failed to invoke toStringBuilder: " + e.getMessage());
        }
    }

    @Test
    public void testAppendPropertyWithTailPointer() {
        // Test that appendProperty also works correctly with tail pointers
        JsonPointer original = JsonPointer.compile("/a/b/c");
        JsonPointer tail = original.tail(); // "/b/c"

        JsonPointer result = tail.appendProperty("d");

        JsonPointer expected = JsonPointer.compile("/b/c/d");

        assertEquals("appendProperty on tail pointer", 
                     expected.toString(), result.toString());
        assertEquals(expected, result);
    }

    @Test
    public void testAppendIndexWithTailPointer() {
        // Test that appendIndex also works correctly with tail pointers
        JsonPointer original = JsonPointer.compile("/a/b/c");
        JsonPointer tail = original.tail(); // "/b/c"

        JsonPointer result = tail.appendIndex(3);

        JsonPointer expected = JsonPointer.compile("/b/c/3");

        assertEquals("appendIndex on tail pointer", 
                     expected.toString(), result.toString());
        assertEquals(expected, result);
    }

    @Test
    public void testHashCodeConsistency() {
        // Verify hashCode uses toString() which respects offset
        JsonPointer original = JsonPointer.compile("/a/b/c");
        JsonPointer tail = original.tail();

        // Both should have same hashCode as their string representations
        assertEquals(tail.toString().hashCode(), tail.hashCode());

        // Different pointers with same string representation should have same hashCode
        JsonPointer compiledTail = JsonPointer.compile("/b/c");
        assertEquals(compiledTail.hashCode(), tail.hashCode());
    }
}

