        Version v1 = new Version(1, 0, 0, "", "group", "artifact");
        Version v2 = new Version(1, 0, 0, null, "group", "artifact");

        // According to isSnapshot(), empty string is not a snapshot
        // But equals should still handle it without NPE
        assertFalse("Empty string snapshot should not equal null snapshot", v1.equals(v2));
        assertFalse("Null snapshot should not equal empty string snapshot", v2.equals(v1));
    }

    @Test
    public void testEqualsAgainstNull() {
        Version v = new Version(1, 0, 0, null, "group", "artifact");
        assertFalse("Version should not equal null", v.equals(null));
