package com.fasterxml.jackson.core;

import org.junit.Test;
import static org.junit.Assert.*;

public class VersionEqualsHashCodeTest {

    @Test
    public void testEqualsWithNullSnapshotInfo() {
        // Test case 1: Both have null snapshot info, all other fields equal
        Version v1 = new Version(1, 2, 3, null, "com.fasterxml.jackson.core", "jackson-core");
        Version v2 = new Version(1, 2, 3, null, "com.fasterxml.jackson.core", "jackson-core");
        assertTrue("Versions with null snapshot info should be equal", v1.equals(v2));
        assertTrue("Equals should be symmetric", v2.equals(v1));

        // Test case 2: First has null snapshot, second has non-null snapshot
        Version v3 = new Version(1, 2, 3, null, "com.fasterxml.jackson.core", "jackson-core");
        Version v4 = new Version(1, 2, 3, "SNAPSHOT", "com.fasterxml.jackson.core", "jackson-core");
        assertFalse("Version with null snapshot should not equal version with non-null snapshot", v3.equals(v4));
        assertFalse("Equals should be symmetric", v4.equals(v3));

        // Test case 3: First has non-null snapshot, second has null snapshot
        Version v5 = new Version(1, 2, 3, "SNAPSHOT", "com.fasterxml.jackson.core", "jackson-core");
        Version v6 = new Version(1, 2, 3, null, "com.fasterxml.jackson.core", "jackson-core");
        assertFalse("Version with non-null snapshot should not equal version with null snapshot", v5.equals(v6));
        assertFalse("Equals should be symmetric", v6.equals(v5));

        // Test case 4: Both have same non-null snapshot info
        Version v7 = new Version(1, 2, 3, "SNAPSHOT", "com.fasterxml.jackson.core", "jackson-core");
        Version v8 = new Version(1, 2, 3, "SNAPSHOT", "com.fasterxml.jackson.core", "jackson-core");
        assertTrue("Versions with same non-null snapshot info should be equal", v7.equals(v8));
        assertTrue("Equals should be symmetric", v8.equals(v7));

        // Test case 5: Both have different non-null snapshot info
        Version v9 = new Version(1, 2, 3, "SNAPSHOT", "com.fasterxml.jackson.core", "jackson-core");
        Version v10 = new Version(1, 2, 3, "ALPHA", "com.fasterxml.jackson.core", "jackson-core");
        assertFalse("Versions with different non-null snapshot info should not be equal", v9.equals(v10));
        assertFalse("Equals should be symmetric", v10.equals(v9));
    }

    @Test
    public void testEqualsWithNullSnapshotInfoAndOtherFieldsDifferent() {
        // Ensure snapshot comparison doesn't affect other field comparisons
        Version v1 = new Version(1, 2, 3, null, "com.fasterxml.jackson.core", "jackson-core");
        Version v2 = new Version(2, 2, 3, null, "com.fasterxml.jackson.core", "jackson-core");
        assertFalse("Different major version should not be equal", v1.equals(v2));

        Version v3 = new Version(1, 2, 3, null, "com.fasterxml.jackson.core", "jackson-core");
        Version v4 = new Version(1, 3, 3, null, "com.fasterxml.jackson.core", "jackson-core");
        assertFalse("Different minor version should not be equal", v3.equals(v4));

        Version v5 = new Version(1, 2, 3, null, "com.fasterxml.jackson.core", "jackson-core");
        Version v6 = new Version(1, 2, 4, null, "com.fasterxml.jackson.core", "jackson-core");
        assertFalse("Different patch level should not be equal", v5.equals(v6));

        Version v7 = new Version(1, 2, 3, null, "com.fasterxml.jackson.core", "jackson-core");
        Version v8 = new Version(1, 2, 3, null, "com.fasterxml.jackson.core", "jackson-databind");
        assertFalse("Different artifact ID should not be equal", v7.equals(v8));

        Version v9 = new Version(1, 2, 3, null, "com.fasterxml.jackson.core", "jackson-core");
        Version v10 = new Version(1, 2, 3, null, "com.fasterxml.jackson", "jackson-core");
        assertFalse("Different group ID should not be equal", v9.equals(v10));
    }

    @Test
    public void testHashCodeWithNullSnapshotInfo() {
        // Hash code should be consistent with equals
        Version v1 = new Version(1, 2, 3, null, "com.fasterxml.jackson.core", "jackson-core");
        Version v2 = new Version(1, 2, 3, null, "com.fasterxml.jackson.core", "jackson-core");

        // If equals returns true, hash codes must be equal
        if (v1.equals(v2)) {
            assertEquals("Equal objects must have equal hash codes", v1.hashCode(), v2.hashCode());
        }

        // Test with non-null snapshot
        Version v3 = new Version(1, 2, 3, "SNAPSHOT", "com.fasterxml.jackson.core", "jackson-core");
        Version v4 = new Version(1, 2, 3, "SNAPSHOT", "com.fasterxml.jackson.core", "jackson-core");

        if (v3.equals(v4)) {
            assertEquals("Equal objects must have equal hash codes", v3.hashCode(), v4.hashCode());
        }

        // Different snapshot should (usually) produce different hash codes
        Version v5 = new Version(1, 2, 3, null, "com.fasterxml.jackson.core", "jackson-core");
        Version v6 = new Version(1, 2, 3, "SNAPSHOT", "com.fasterxml.jackson.core", "jackson-core");

        // Note: Not requiring different hash codes for unequal objects, but they often will be
        assertNotEquals("Different snapshot info should typically produce different hash codes", 
                       v5.hashCode(), v6.hashCode());
    }

    @Test
    public void testEqualsContract() {
        // Reflexivity
        Version v1 = new Version(1, 2, 3, null, "com.fasterxml.jackson.core", "jackson-core");
        assertTrue("Object should equal itself", v1.equals(v1));

        // Symmetry tested in other methods

        // Transitivity
        Version v2 = new Version(1, 2, 3, null, "com.fasterxml.jackson.core", "jackson-core");
        Version v3 = new Version(1, 2, 3, null, "com.fasterxml.jackson.core", "jackson-core");

        if (v1.equals(v2) && v2.equals(v3)) {
            assertTrue("Equals should be transitive", v1.equals(v3));
        }

        // Consistency
        boolean firstResult = v1.equals(v2);
        boolean secondResult = v1.equals(v2);
        assertEquals("Multiple calls to equals should return same result", firstResult, secondResult);

        // Non-nullity
        assertFalse("Object should not equal null", v1.equals(null));

        // Different class
        assertFalse("Object should not equal object of different class", v1.equals("not a Version"));
    }

    @Test
    public void testEqualsWithUnknownVersion() {
        Version unknown = Version.unknownVersion();
        Version v1 = new Version(0, 0, 0, null, null, null);

        // UNKNOWN_VERSION is a static instance with all null fields
        assertTrue("unknownVersion() should equal itself", unknown.equals(unknown));

        // A newly created Version with same fields should equal UNKNOWN_VERSION
        assertTrue("Version with same fields as UNKNOWN_VERSION should equal it", v1.equals(unknown));
        assertTrue("Equals should be symmetric", unknown.equals(v1));
    }

    @Test
    public void testIsSnapshotWithNullSnapshotInfo() {
