package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.Base64Variant;
import com.fasterxml.jackson.core.Base64Variants;
import com.fasterxml.jackson.core.JsonFactory;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import org.junit.Test;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.fail;

public class UTF8StreamJsonParserBase64PaddingTest {

    /**
     * Test that Base64 decoding with missing padding succeeds when the variant
     * is configured with PADDING_ALLOWED.
     * This test should fail before the patch (because usesPadding() returns true
     * for MIME variants, causing an exception) and pass after the patch
     * (because requiresPaddingOnRead() returns false for PADDING_ALLOWED).
     */
    @Test
    public void testReadBinaryWithMissingPaddingAndPaddingAllowed() throws IOException {
        // Create a Base64 variant that uses padding but allows missing padding on read
        Base64Variant variant = Base64Variants.MIME_NO_LINEFEEDS
                .withReadPadding(Base64Variant.PaddingReadBehaviour.PADDING_ALLOWED);

        // Base64 string "AA" (two characters) without padding. Decodes to single byte 0x00.
        // Proper padded form would be "AA==".
        String json = "\"AA\"";
        byte[] expected = new byte[] { 0x00 };

        InputStream in = new ByteArrayInputStream(json.getBytes(StandardCharsets.UTF_8));
        JsonFactory factory = new JsonFactory();
        JsonParser parser = factory.createParser(in);

        // Move to the string value token
        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());

        ByteArrayOutputStream out = new ByteArrayOutputStream();

        // This should succeed after the patch, but throw an exception before the patch
        try {
            int count = parser.readBinaryValue(variant, out);
            byte[] actual = out.toByteArray();
            assertArrayEquals(expected, actual);
            assertEquals(1, count);
        } catch (IOException e) {
            // Before the patch, we expect a MissingPadding exception
            // The exception message contains "missing padding"
            if (e.getMessage().contains("missing padding")) {
                // This is the expected failure before the patch
                fail("MissingPadding exception thrown despite PADDING_ALLOWED: " + e.getMessage());
            } else {
                throw e;
            }
        }
        parser.close();
    }

    /**
     * Test that Base64 decoding with missing padding still throws when the variant
     * requires padding on read (default behavior).
     */
    @Test
    public void testReadBinaryWithMissingPaddingAndPaddingRequired() throws IOException {
        // Use default MIME variant which requires padding
        Base64Variant variant = Base64Variants.MIME_NO_LINEFEEDS;
        // Verify that it requires padding on read (default)
        // Note: We cannot call getReadPadding() as it doesn't exist in Base64Variant
        // Instead we rely on the fact that default variant requires padding

        String json = "\"AA\"";
        InputStream in = new ByteArrayInputStream(json.getBytes(StandardCharsets.UTF_8));
        JsonFactory factory = new JsonFactory();
        JsonParser parser = factory.createParser(in);

        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());

        ByteArrayOutputStream out = new ByteArrayOutputStream();

        try {
            parser.readBinaryValue(variant, out);
            fail("Expected IOException due to missing padding");
        } catch (IOException e) {
            // Expected - missing padding should throw when required
            // Check that the message mentions padding
            assertNotNull(e.getMessage());
        }
        parser.close();
    }

    /**
     * Test with a longer Base64 string missing padding (3 characters -> 2 bytes).
     * Proper padded form would be "AAA=".
     */
    @Test
    public void testReadBinaryWithMissingPaddingThreeChars() throws IOException {
        Base64Variant variant = Base64Variants.MIME_NO_LINEFEEDS
                .withReadPadding(Base64Variant.PaddingReadBehaviour.PADDING_ALLOWED);

        // Base64 "AAA" (three characters) without padding. Decodes to two bytes 0x00, 0x00.
        String json = "\"AAA\"";
        byte[] expected = new byte[] { 0x00, 0x00 };

        InputStream in = new ByteArrayInputStream(json.getBytes(StandardCharsets.UTF_8));
        JsonFactory factory = new JsonFactory();
        JsonParser parser = factory.createParser(in);

        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());

        ByteArrayOutputStream out = new ByteArrayOutputStream();

        try {
            int count = parser.readBinaryValue(variant, out);
            byte[] actual = out.toByteArray();
            assertArrayEquals(expected, actual);
            assertEquals(2, count);
        } catch (IOException e) {
            if (e.getMessage().contains("missing padding")) {
                fail("MissingPadding exception thrown despite PADDING_ALLOWED: " + e.getMessage());
            } else {
                throw e;
            }
        }
        parser.close();
    }

    /**
     * Test with properly padded Base64 string to ensure normal decoding still works.
     */
    @Test
    public void testReadBinaryWithProperPadding() throws IOException {
        Base64Variant variant = Base64Variants.MIME_NO_LINEFEEDS
                .withReadPadding(Base64Variant.PaddingReadBehaviour.PADDING_ALLOWED);

        // Properly padded Base64 "AA=="
        String json = "\"AA==\"";
        byte[] expected = new byte[] { 0x00 };

        InputStream in = new ByteArrayInputStream(json.getBytes(StandardCharsets.UTF_8));
        JsonFactory factory = new JsonFactory();
        JsonParser parser = factory.createParser(in);

        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());

        ByteArrayOutputStream out = new ByteArrayOutputStream();

        int count = parser.readBinaryValue(variant, out);
        byte[] actual = out.toByteArray();
        assertArrayEquals(expected, actual);
        assertEquals(1, count);
        parser.close();
    }

    /**
     * Test integration with ObjectMapper deserialization of a byte array field.
     * Since we cannot use databind in core module, we simulate the behavior
     * by directly using the parser with a custom ObjectCodec.
     */
    @Test
    public void testObjectMapperDeserializationWithMissingPadding() throws IOException {
        // Create a Base64 variant that allows missing padding
        Base64Variant variant = Base64Variants.MIME_NO_LINEFEEDS
                .withReadPadding(Base64Variant.PaddingReadBehaviour.PADDING_ALLOWED);

        // Simple class with a byte array field
        class Output {
            public byte[] diff;
        }

        // Base64 for "Hello" (5 bytes) without padding: "SGVsbG8"
        // Proper padded form would be "SGVsbG8="
        String json = "{\"diff\":\"SGVsbG8\"}";
        byte[] expected = "Hello".getBytes(StandardCharsets.UTF_8);

        InputStream in = new ByteArrayInputStream(json.getBytes(StandardCharsets.UTF_8));
        JsonFactory factory = new JsonFactory();
        JsonParser parser = factory.createParser(in);

        // Parse JSON structure manually
        assertEquals(JsonToken.START_OBJECT, parser.nextToken());
        assertEquals(JsonToken.FIELD_NAME, parser.nextToken());
        assertEquals("diff", parser.getCurrentName());
        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());

        ByteArrayOutputStream out = new ByteArrayOutputStream();

        try {
            int count = parser.readBinaryValue(variant, out);
            byte[] actual = out.toByteArray();
            assertArrayEquals(expected, actual);
            assertEquals(5, count);
        } catch (IOException e) {
            if (e.getMessage().contains("missing padding")) {
                fail("MissingPadding exception thrown despite PADDING_ALLOWED: " + e.getMessage());
            } else {
                throw e;
            }
        }
        parser.close();
    }
}

