package com.fasterxml.jackson.core;

import org.junit.Test;
import static org.junit.Assert.*;

public class JsonPointerAppendTailTest {

    @Test
    public void testAppendPropertyOnChainedTailPointers() {
        // Create original pointer with multiple segments
        JsonPointer original = JsonPointer.compile("/a/b/c/d");

        // Get first tail (removes "/a")
        JsonPointer tail1 = original.tail();
        assertEquals("/b/c/d", tail1.toString());

        // Get second tail from first tail (removes "/b")
        JsonPointer tail2 = tail1.tail();
        assertEquals("/c/d", tail2.toString());

        // Append property to the double-tail pointer
        JsonPointer result = tail2.appendProperty("e");

        // Verify correct concatenation with offset handling
        assertEquals("/c/d/e", result.toString());
    }

    @Test
    public void testAppendTailPointer() {
        // Test the bug fix for #1168: append(JsonPointer.tail()) should not include original pointer
        JsonPointer original = JsonPointer.compile("/a1/b/c");
        JsonPointer tailPointer = original.tail(); // Should be "/b/c"
        JsonPointer other = JsonPointer.compile("/a2");
        JsonPointer concatenated = other.append(tailPointer);

        // Expected: "/a2/b/c" (not "/a2/a1/b/c")
        assertEquals("/a2/b/c", concatenated.toString());
        assertEquals(JsonPointer.compile("/a2/b/c"), concatenated);
    }

    @Test
    public void testAppendPropertyWithTailPointer() {
        // Test appendProperty with tail pointers
        JsonPointer original = JsonPointer.compile("/x/y/z");
        JsonPointer tail = original.tail(); // "/y/z"
        JsonPointer result = tail.appendProperty("w");

        assertEquals("/y/z/w", result.toString());
    }

    @Test
    public void testAppendIndexWithTailPointer() {
        // Test appendIndex with tail pointers
        JsonPointer original = JsonPointer.compile("/arr/0/1");
        JsonPointer tail = original.tail(); // "/0/1"
        JsonPointer result = tail.appendIndex(2);

        assertEquals("/0/1/2", result.toString());
    }

    @Test
    public void testMultipleTailOperations() {
        // Test multiple tail operations followed by append
        JsonPointer ptr = JsonPointer.compile("/a/b/c/d/e");
        JsonPointer tail1 = ptr.tail(); // "/b/c/d/e"
        JsonPointer tail2 = tail1.tail(); // "/c/d/e"
        JsonPointer tail3 = tail2.tail(); // "/d/e"

        JsonPointer other = JsonPointer.compile("/x");
        JsonPointer result = other.append(tail3);

        assertEquals("/x/d/e", result.toString());
    }

    @Test
    public void testAppendEmptyTail() {
        // Test appending an empty tail pointer
        JsonPointer ptr = JsonPointer.compile("/a");
        JsonPointer tail = ptr.tail(); // "" (empty)
        JsonPointer other = JsonPointer.compile("/b");
        JsonPointer result = other.append(tail);

        assertEquals("/b", result.toString());
        assertEquals(other, result);
    }

    @Test
    public void testAppendToEmptyPointer() {
        // Test appending a tail pointer to empty pointer
        JsonPointer ptr = JsonPointer.compile("/a/b");
        JsonPointer tail = ptr.tail(); // "/b"
        JsonPointer empty = JsonPointer.empty();
        JsonPointer result = empty.append(tail);

        assertEquals("/b", result.toString());
        assertEquals(tail, result);
    }

    @Test
    public void testTailAndAppendPropertyChain() {
        // Complex chain of tail and appendProperty operations
        JsonPointer original = JsonPointer.compile("/root/item/subitem");
        JsonPointer tail = original.tail(); // "/item/subitem"
        JsonPointer withProperty = tail.appendProperty("field"); // "/item/subitem/field"
        JsonPointer tail2 = withProperty.tail(); // "/subitem/field"
        JsonPointer result = tail2.appendProperty("value"); // "/subitem/field/value"

        assertEquals("/subitem/field/value", result.toString());
    }

    @Test
    public void testAppendPropertyEscapingWithTail() {
        // Test that property escaping works correctly with tail pointers
        JsonPointer original = JsonPointer.compile("/a/b");
        JsonPointer tail = original.tail(); // "/b"
        JsonPointer result = tail.appendProperty("c/d"); // Should escape the slash

        // The property "c/d" should be escaped to "c~1d"
        assertEquals("/b/c~1d", result.toString());
    }

    @Test
    public void testHashCodeConsistencyWithTail() {
        // Ensure hashCode is consistent with toString() for tail pointers
