        assertFalse("Null vs non-null snapshot should be unequal", v3.equals(v4));

        // Scenario 3: First version non-null snapshot, second null
        Version v5 = new Version(2, 16, 0, "SNAPSHOT", "com.fasterxml.jackson.core", "jackson-core");
        Version v6 = new Version(2, 16, 0, null, "com.fasterxml.jackson.core", "jackson-core");
