        ((NonBlockingByteBufferJsonParser) parserDisabled).feedInput(buffer);

        parserDisabled.nextToken(); // START_OBJECT
        parserDisabled.nextToken(); // FIELD_NAME "fieldName"
        String field1Disabled = parserDisabled.getCurrentName();
        parserDisabled.nextToken(); // VALUE_TRUE
        parserDisabled.nextToken(); // FIELD_NAME "fieldName" again
