package com.fasterxml.jackson.core;

import org.junit.Test;
import static org.junit.Assert.*;

public class JsonPointerAppendTailTest {

    @Test
    public void testAppendTailPointerFix() {
        // Original pointer with multiple segments
        JsonPointer original = JsonPointer.compile("/a1/b/c");

        // Get tail pointer (should skip first segment)
        JsonPointer tail = original.tail();
        assertEquals("/b/c", tail.toString());

        // Base pointer to append to
        JsonPointer base = JsonPointer.compile("/a2");

        // Append tail to base
        JsonPointer result = base.append(tail);

        // Verify correct concatenation (without duplicate segments)
        assertEquals("/a2/b/c", result.toString());
        assertEquals(JsonPointer.compile("/a2/b/c"), result);
    }

    @Test
    public void testAppendToEmptyPointer() {
        JsonPointer empty = JsonPointer.empty();
        JsonPointer tail = JsonPointer.compile("/x/y");

        JsonPointer result = empty.append(tail);
        assertSame(tail, result);
    }

    @Test
    public void testAppendEmptyPointer() {
        JsonPointer base = JsonPointer.compile("/a");
        JsonPointer empty = JsonPointer.empty();

        JsonPointer result = base.append(empty);
        assertSame(base, result);
    }

    @Test
    public void testAppendSingleSegmentTail() {
        JsonPointer original = JsonPointer.compile("/a1");
        JsonPointer tail = original.tail();
        assertSame(JsonPointer.empty(), tail);

        JsonPointer base = JsonPointer.compile("/a2");
        JsonPointer result = base.append(tail);
        assertSame(base, result);
    }

    @Test
    public void testAppendMultipleSegments() {
        JsonPointer base = JsonPointer.compile("/root");
        JsonPointer tail = JsonPointer.compile("/sub1/sub2");

        JsonPointer result = base.append(tail);
        assertEquals("/root/sub1/sub2", result.toString());
    }

    @Test
    public void testAppendToPointerWithTrailingSlash() {
        JsonPointer base = JsonPointer.compile("/path/");
        JsonPointer tail = JsonPointer.compile("/child");

        JsonPointer result = base.append(tail);
        assertEquals("/path//child", result.toString());
    }

    @Test
    public void testChainedAppendOperations() {
        JsonPointer first = JsonPointer.compile("/start");
        JsonPointer second = JsonPointer.compile("/middle");
        JsonPointer third = JsonPointer.compile("/end");

        JsonPointer result = first.append(second).append(third);
        assertEquals("/start/middle/end", result.toString());
    }

    @Test
    public void testAppendTailWithEscapedCharacters() {
        JsonPointer original = JsonPointer.compile("/a~1b/c~0d");
        JsonPointer tail = original.tail();
        assertEquals("/c~0d", tail.toString());

        JsonPointer base = JsonPointer.compile("/x~1y");
        JsonPointer result = base.append(tail);
        assertEquals("/x~1y/c~0d", result.toString());
    }
}

