import org.junit.Test;

import java.io.ByteArrayOutputStream;
import java.io.IOException;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.fail;

public class ReaderBasedJsonParserBase64PaddingTest {

    // Helper method to create a ReaderBasedJsonParser with custom input
    private ReaderBasedJsonParser createParser(String json) throws IOException {
        JsonFactory factory = new JsonFactory();
        return (ReaderBasedJsonParser) factory.createParser(json);
    }

    @Test
    public void testStandaloneBase64TwoCharsWithPaddingAllowed() throws IOException {
        String json = "\"AA\""; // "AA" decodes to [0x00]
        Base64Variant variant = Base64Variants.MIME_NO_LINEFEEDS
            .withReadPadding(Base64Variant.PaddingReadBehaviour.PADDING_ALLOWED);

        try (ReaderBasedJsonParser parser = createParser(json)) {
            assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
            byte[] result = parser.getBinaryValue(variant);
            assertArrayEquals(new byte[]{0}, result);
        }
    }

    @Test
    public void testStandaloneBase64TwoCharsWithPaddingRequired() throws IOException {
        String json = "\"AA\"";
        Base64Variant variant = Base64Variants.MIME_NO_LINEFEEDS; // Default requires padding

        try (ReaderBasedJsonParser parser = createParser(json)) {
            assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
            parser.getBinaryValue(variant);
            fail("Expected exception for missing padding when required");
        } catch (Exception e) {
            assertNotNull(e);
        }
    }

    @Test
    public void testStandaloneBase64ThreeCharsWithPaddingAllowed() throws IOException {
        String json = "\"AAA\""; // "AAA" decodes to [0x00, 0x00]
