import com.fasterxml.jackson.core.sym.ByteQuadsCanonicalizer;
import org.junit.Test;

import java.io.ByteArrayInputStream;
import java.io.DataInput;
import java.io.DataInputStream;
import java.io.IOException;
import java.lang.reflect.Field;
import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;

import static org.junit.Assert.*;

public class JsonFactoryCanonicalizationTest {

    // Helper method to access parser's symbol table via reflection with hierarchy traversal
    private ByteQuadsCanonicalizer getSymbols(JsonParser parser) throws Exception {
        Class<?> clazz = parser.getClass();
        while (clazz != null) {
            try {
                Field symbolsField = clazz.getDeclaredField("_symbols");
                symbolsField.setAccessible(true);
                return (ByteQuadsCanonicalizer) symbolsField.get(parser);
            } catch (NoSuchFieldException e) {
                clazz = clazz.getSuperclass();
            }
        }
        throw new NoSuchFieldException("_symbols");
    }

    // Functional interface for parser creation
    @FunctionalInterface
    private interface ParserCreator {
        JsonParser create(JsonFactory factory) throws IOException;
    }

    // Helper method to test canonicalization setting for a parser type
    private void testCanonicalizationForParserType(ParserCreator parserCreator) throws Exception {
        // Test with canonicalization DISABLED
        JsonFactory factoryDisabled = JsonFactory.builder()
                .disable(JsonFactory.Feature.CANONICALIZE_FIELD_NAMES)
                .build();

        JsonParser parserDisabled = parserCreator.create(factoryDisabled);
        ByteQuadsCanonicalizer symbolsDisabled = getSymbols(parserDisabled);
        assertFalse("Canonicalization should be disabled", symbolsDisabled.isCanonicalizing());

        // Feed data to non-blocking parsers
        if (parserDisabled instanceof NonBlockingJsonParser) {
            byte[] data = "{\"field1\":1,\"field2\":2}".getBytes(StandardCharsets.UTF_8);
            ((NonBlockingJsonParser) parserDisabled).feedInput(data, 0, data.length);
            ((NonBlockingJsonParser) parserDisabled).endOfInput();
        } else if (parserDisabled instanceof NonBlockingByteBufferJsonParser) {
            byte[] data = "{\"field1\":1,\"field2\":2}".getBytes(StandardCharsets.UTF_8);
            ByteBuffer buf = ByteBuffer.wrap(data);
            ((NonBlockingByteBufferJsonParser) parserDisabled).feedInput(buf);
            ((NonBlockingByteBufferJsonParser) parserDisabled).endOfInput();
        }

        // Parse tokens and validate
        assertEquals(JsonToken.START_OBJECT, parserDisabled.nextToken());
        assertEquals(JsonToken.FIELD_NAME, parserDisabled.nextToken());
        assertEquals("field1", parserDisabled.getCurrentName());
        assertEquals(JsonToken.VALUE_NUMBER_INT, parserDisabled.nextToken());
        assertEquals(JsonToken.FIELD_NAME, parserDisabled.nextToken());
        assertEquals("field2", parserDisabled.getCurrentName());
        assertEquals("Symbol table should be placeholder when canonicalization disabled", 
                     -1, symbolsDisabled.size());

        parserDisabled.close();

        // Test with canonicalization ENABLED
        JsonFactory factoryEnabled = JsonFactory.builder()
                .enable(JsonFactory.Feature.CANONICALIZE_FIELD_NAMES)
                .build();

        JsonParser parserEnabled = parserCreator.create(factoryEnabled);
        ByteQuadsCanonicalizer symbolsEnabled = getSymbols(parserEnabled);
        assertTrue("Canonicalization should be enabled", symbolsEnabled.isCanonicalizing());

        // Feed data to non-blocking parsers
        if (parserEnabled instanceof NonBlockingJsonParser) {
            byte[] data = "{\"field1\":1,\"field2\":2}".getBytes(StandardCharsets.UTF_8);
            ((NonBlockingJsonParser) parserEnabled).feedInput(data, 0, data.length);
