            ((NonBlockingByteBufferJsonParser) parserEnabled).endOfInput();
        }

        // Parse tokens and validate
        assertEquals(JsonToken.START_OBJECT, parserEnabled.nextToken());
        assertEquals(JsonToken.FIELD_NAME, parserEnabled.nextToken());
        assertEquals("field1", parserEnabled.getCurrentName());
        assertEquals(JsonToken.VALUE_NUMBER_INT, parserEnabled.nextToken());
        assertEquals(JsonToken.FIELD_NAME, parserEnabled.nextToken());
        assertEquals("field2", parserEnabled.getCurrentName());
        assertTrue("Symbol table should contain entries when canonicalization enabled", 
                   symbolsEnabled.size() > 0);

        parserEnabled.close();
    }

    // Test DataInput parser
    @Test
    public void testDataInputParserCanonicalization() throws Exception {
        testCanonicalizationForParserType(factory -> {
            byte[] jsonBytes = "{\"field1\":1,\"field2\":2}".getBytes(StandardCharsets.UTF_8);
            ByteArrayInputStream bais = new ByteArrayInputStream(jsonBytes);
