public class UTF8DataInputJsonParserCanonicalizationTest {

    private JsonFactory createFactoryWithoutCanonicalization() {
        return JsonFactory.builder()
                .disable(JsonFactory.Feature.CANONICALIZE_FIELD_NAMES)
                .build();
    }

    private JsonFactory createFactoryWithCanonicalization() {
        return JsonFactory.builder()
                .enable(JsonFactory.Feature.CANONICALIZE_FIELD_NAMES)
                .build();
    }

    @Test
    public void testDataInputParserWithoutCanonicalization() throws Exception {
        JsonFactory factory = createFactoryWithoutCanonicalization();
        testDataInputParser(factory, "testField", false);
        testDataInputParser(factory, "testFieldWithÜnicode", false);
        testDataInputParser(factory, "test\u0800Field", false); // 3-byte char
        testDataInputParser(factory, "test\uD83D\uDE00Field", false); // 4-byte char (emoji)
    }

    @Test
    public void testDataInputParserWithCanonicalization() throws Exception {
        JsonFactory factory = createFactoryWithCanonicalization();
        testDataInputParser(factory, "testField", true);
        testDataInputParser(factory, "testFieldWithÜnicode", true);
        testDataInputParser(factory, "test\u0800Field", true); // 3-byte char
        testDataInputParser(factory, "test\uD83D\uDE00Field", true); // 4-byte char (emoji)
    }

    private void testDataInputParser(JsonFactory factory, String fieldName, boolean expectCanonicalizing) throws Exception {
        String json = "{\"" + fieldName + "\":\"value\"}";
        DataInput dataInput = new ByteArrayDataInput(json.getBytes(StandardCharsets.UTF_8));

        try (JsonParser parser = factory.createParser(dataInput)) {
            parser.nextToken(); // START_OBJECT
            parser.nextToken(); // FIELD_NAME
            assertEquals(fieldName, parser.getCurrentName());

            ByteQuadsCanonicalizer symbols = getSymbols(parser);
            assertEquals(expectCanonicalizing, symbols.isCanonicalizing());
        }
    }

    @Test
