@RunWith(Parameterized.class)
public class ReaderBasedJsonParserBase64PaddingTest {

    @Parameterized.Parameters(name = "{0}")
    public static Object[] parserTypes() {
        return ParserType.values();
    }

    enum ParserType {
        READER_BASED,
        UTF8_STREAM,
        UTF8_DATA_INPUT
    }

    private final ParserType parserType;

    public ReaderBasedJsonParserBase64PaddingTest(ParserType parserType) {
        this.parserType = parserType;
    }

    private JsonParser createParser(String json, Base64Variant variant) throws IOException {
        IOContext ioContext = new IOContext(new BufferRecycler(), json, false);
        switch (parserType) {
            case READER_BASED:
                Reader reader = new StringReader(json);
                CharsToNameCanonicalizer sym = CharsToNameCanonicalizer.createRoot();
                char[] buffer = new char[1024];
                return new ReaderBasedJsonParser(ioContext, JsonFactory.Feature.collectDefaults(),
                        reader, null, sym, buffer, 0, 0, true);
            case UTF8_STREAM:
                byte[] jsonBytes = json.getBytes(StandardCharsets.UTF_8);
                InputStream in = new ByteArrayInputStream(jsonBytes);
                ByteQuadsCanonicalizer can = ByteQuadsCanonicalizer.createRoot();
                return new UTF8StreamJsonParser(ioContext, JsonFactory.Feature.collectDefaults(),
                        in, null, can, jsonBytes, 0, jsonBytes.length, true);
            case UTF8_DATA_INPUT:
