    @Test
    public void testAppendWithTailPointer() {
        // Original pointer with multiple segments
        JsonPointer original = JsonPointer.compile("/a1/b/c");

        // Get tail pointer (should represent "/b/c")
        JsonPointer tail = original.tail();

        // Create another pointer to append to
        JsonPointer other = JsonPointer.compile("/a2");

        // Append the tail pointer
        JsonPointer result = other.append(tail);

        // Expected: "/a2/b/c"
        // Buggy behavior before patch: "/a2/a1/b/c"
        JsonPointer expected = JsonPointer.compile("/a2/b/c");

        // Verify the result matches expected
        assertEquals("Appending tail pointer should produce correct concatenation", 
                     expected.toString(), result.toString());

        // Also verify the pointers are equal
        assertEquals(expected, result);
    }

    @Test
    public void testAppendWithTailPointerMultipleLevels() {
        // Test with deeper nesting
        JsonPointer original = JsonPointer.compile("/a/b/c/d/e");
        JsonPointer tail = original.tail(); // Should be "/b/c/d/e"
        JsonPointer other = JsonPointer.compile("/x/y");
        JsonPointer result = other.append(tail);

        JsonPointer expected = JsonPointer.compile("/x/y/b/c/d/e");
        assertEquals("Appending deep tail pointer should work correctly",
                     expected.toString(), result.toString());
        assertEquals(expected, result);
    }

    @Test
    public void testAppendWithEmptyPointer() {
        // Test edge case with empty pointer
        JsonPointer empty = JsonPointer.compile("");
        JsonPointer original = JsonPointer.compile("/a/b/c");
        JsonPointer tail = original.tail(); // "/b/c"

        // Append tail to empty pointer
        JsonPointer result = empty.append(tail);

        // Should just be the tail
        JsonPointer expected = JsonPointer.compile("/b/c");
        assertEquals("Appending tail to empty pointer should work",
                     expected.toString(), result.toString());
        assertEquals(expected, result);
    }

