        JsonPointer ptr = JsonPointer.compile("/a/b");
        JsonPointer result = ptr.appendIndex(5);

        JsonPointer expected = JsonPointer.compile("/a/b/5");
        assertEquals("appendIndex should work correctly",
                     expected.toString(), result.toString());
        assertEquals(expected, result);
    }

