public class VersionEqualsTest {

    @Test
    public void testEqualsWithNullSnapshotInfo() {
        // Test case 1: Both versions have null snapshot info - should be equal
        Version v1 = new Version(1, 0, 0, null, "com.fasterxml.jackson.core", "jackson-core");
        Version v2 = new Version(1, 0, 0, null, "com.fasterxml.jackson.core", "jackson-core");
        assertTrue("Versions with null snapshot info should be equal", v1.equals(v2));
        assertTrue("Equals should be symmetric", v2.equals(v1));

        // Test case 2: One has null snapshot info, other has non-null - should not be equal
        Version v3 = new Version(1, 0, 0, "SNAPSHOT", "com.fasterxml.jackson.core", "jackson-core");
        assertFalse("Version with null snapshot should not equal version with non-null snapshot", 
                   v1.equals(v3));
        assertFalse("Equals should be symmetric", v3.equals(v1));

        // Test case 3: Both have same non-null snapshot info - should be equal
        Version v4 = new Version(1, 0, 0, "SNAPSHOT", "com.fasterxml.jackson.core", "jackson-core");
        assertTrue("Versions with same non-null snapshot info should be equal", v3.equals(v4));

        // Test case 4: Different non-null snapshot info - should not be equal
        Version v5 = new Version(1, 0, 0, "ALPHA", "com.fasterxml.jackson.core", "jackson-core");
        assertFalse("Versions with different snapshot info should not be equal", v3.equals(v5));
    }

    @Test
    public void testEqualsReflexivityWithNullSnapshot() {
        Version v = new Version(2, 16, 0, null, "com.fasterxml.jackson.core", "jackson-core");
        assertTrue("Version should equal itself", v.equals(v));
    }

    @Test
    public void testEqualsTransitivityWithNullSnapshot() {
        Version v1 = new Version(1, 2, 3, null, "group", "artifact");
        Version v2 = new Version(1, 2, 3, null, "group", "artifact");
        Version v3 = new Version(1, 2, 3, null, "group", "artifact");

        assertTrue("v1 should equal v2", v1.equals(v2));
        assertTrue("v2 should equal v3", v2.equals(v3));
        assertTrue("v1 should equal v3 by transitivity", v1.equals(v3));
    }

    @Test
    public void testEqualsWithAllNullFields() {
        // Using the UNKNOWN_VERSION constant which has all null fields
        Version unknown1 = Version.unknownVersion();
        Version unknown2 = Version.unknownVersion();
        assertTrue("UNKNOWN_VERSION should equal itself", unknown1.equals(unknown2));
    }

    @Test
    public void testHashCodeConsistencyWithNullSnapshot() {
        Version v1 = new Version(1, 0, 0, null, "com.fasterxml.jackson.core", "jackson-core");
        Version v2 = new Version(1, 0, 0, null, "com.fasterxml.jackson.core", "jackson-core");

        // If two objects are equal, their hash codes must be equal
        if (v1.equals(v2)) {
            assertEquals("Equal objects must have equal hash codes", v1.hashCode(), v2.hashCode());
        }

        // Test with non-null snapshot
        Version v3 = new Version(1, 0, 0, "SNAPSHOT", "com.fasterxml.jackson.core", "jackson-core");
        Version v4 = new Version(1, 0, 0, "SNAPSHOT", "com.fasterxml.jackson.core", "jackson-core");

