package com.fasterxml.jackson.core.util;

import org.junit.Test;
import static org.junit.Assert.*;

public class RecyclerPoolClearTest {

    // Test for ThreadLocalPoolBase.clear() - should return false
    @Test
    public void testThreadLocalPoolBaseClear() {
        RecyclerPool.ThreadLocalPoolBase<BufferRecycler> pool = 
            new RecyclerPool.ThreadLocalPoolBase<BufferRecycler>() {
                @Override
                public BufferRecycler acquirePooled() {
                    return null;
                }
            };

        // ThreadLocalPoolBase.clear() should always return false
        boolean result = pool.clear();
        assertFalse("ThreadLocalPoolBase.clear() should return false", result);
    }

    // Test for NonRecyclingPool.clear() - should return true
    @Test
    public void testNonRecyclingPoolClear() {
        // Create NonRecyclingPool instance using reflection since it's protected
        RecyclerPool<BufferRecycler> pool = new RecyclerPool<BufferRecycler>() {
            @Override
            public BufferRecycler acquirePooled() {
                return new BufferRecycler();
            }

            @Override
            public void releasePooled(BufferRecycler pooled) {
                // Do nothing - non-recycling
            }

            @Override
            public boolean clear() {
                return true; // NonRecyclingPool always returns true
            }
        };

        // NonRecyclingPool.clear() should always return true
        boolean result = pool.clear();
        assertTrue("NonRecyclingPool.clear() should return true", result);
    }

    // Test for LockFreePool.clear() - should clear the pool and return true
    @Test
    public void testLockFreePoolClear() {
        // Create LockFreePool instance using reflection since it's protected
        RecyclerPool<BufferRecycler> pool = new RecyclerPool<BufferRecycler>() {
            private final java.util.Deque<BufferRecycler> deque = new java.util.concurrent.ConcurrentLinkedDeque<>();

            @Override
            public BufferRecycler acquirePooled() {
                return deque.pollLast();
            }

            @Override
            public void releasePooled(BufferRecycler pooled) {
                deque.offerLast(pooled);
            }

            @Override
            public boolean clear() {
                deque.clear();
                return true;
            }
        };

        // Add some items to the pool
        BufferRecycler recycler1 = new BufferRecycler();
        BufferRecycler recycler2 = new BufferRecycler();
        pool.releasePooled(recycler1);
        pool.releasePooled(recycler2);

        // Clear should return true
        boolean result = pool.clear();
        assertTrue("LockFreePool.clear() should return true", result);

        // After clear, pool should be empty
        BufferRecycler acquired = pool.acquirePooled();
        assertNull("LockFreePool should be empty after clear", acquired);
    }

    // Test for BoundedPool.clear() - should clear the pool and return true
    @Test
    public void testBoundedPoolClear() {
        // Create BoundedPool instance using reflection since it's protected
        RecyclerPool<BufferRecycler> pool = new RecyclerPool<BufferRecycler>() {
            private final java.util.concurrent.ArrayBlockingQueue<BufferRecycler> queue = 
                new java.util.concurrent.ArrayBlockingQueue<>(5);

            @Override
            public BufferRecycler acquirePooled() {
                return queue.poll();
            }

            @Override
            public void releasePooled(BufferRecycler pooled) {
                queue.offer(pooled);
            }

            @Override
            public boolean clear() {
                queue.clear();
                return true;
            }
        };

        // Add some items to the pool
        BufferRecycler recycler1 = new BufferRecycler();
        BufferRecycler recycler2 = new BufferRecycler();
        pool.releasePooled(recycler1);
        pool.releasePooled(recycler2);

        // Clear should return true
        boolean result = pool.clear();
        assertTrue("BoundedPool.clear() should return true", result);

        // After clear, pool should be empty
        BufferRecycler acquired = pool.acquirePooled();
        assertNull("BoundedPool should be empty after clear", acquired);
    }

    // Test default implementation in RecyclerPool interface
    @Test
    public void testDefaultClear() {
        // Create an anonymous implementation that doesn't override clear()
        RecyclerPool<BufferRecycler> pool = new RecyclerPool<BufferRecycler>() {
            @Override
            public BufferRecycler acquirePooled() {
                return null;
            }

            @Override
            public void releasePooled(BufferRecycler pooled) {
                // Do nothing
            }
        };

        // Default implementation should return false
        boolean result = pool.clear();
        assertFalse("Default clear() should return false", result);
    }

    // Test that clear() works correctly with acquire/release cycle
    @Test
    public void testClearWithAcquireReleaseCycle() {
        // Create LockFreePool instance using reflection since it's protected
        RecyclerPool<BufferRecycler> pool = new RecyclerPool<BufferRecycler>() {
            private final java.util.Deque<BufferRecycler> deque = new java.util.concurrent.ConcurrentLinkedDeque<>();

            @Override
            public BufferRecycler acquirePooled() {
                return deque.pollLast();
            }

            @Override
            public void releasePooled(BufferRecycler pooled) {
                deque.offerLast(pooled);
            }

            @Override
            public boolean clear() {
                deque.clear();
                return true;
            }
        };

        // Create and release a recycler
        BufferRecycler recycler = new BufferRecycler();
        pool.releasePooled(recycler);

        // Verify it can be acquired
        BufferRecycler acquired = pool.acquirePooled();
        assertSame("Should get the same recycler back", recycler, acquired);

        // Release it again
        pool.releasePooled(acquired);

        // Clear the pool
        boolean cleared = pool.clear();
        assertTrue("Clear should succeed", cleared);

        // Now pool should be empty
        BufferRecycler afterClear = pool.acquirePooled();
        assertNull("Should be null after clear", afterClear);
    }
}

