package com.fasterxml.jackson.core;

import org.junit.Test;
import static org.junit.Assert.*;

public class VersionTest {

    @Test
    public void testHashCodeIncludesSnapshotInfo() {
        // Create two versions that are identical except for snapshot info
        Version v1 = new Version(1, 2, 3, "alpha", "com.example", "artifact");
        Version v2 = new Version(1, 2, 3, "beta", "com.example", "artifact");

        int hash1 = v1.hashCode();
        int hash2 = v2.hashCode();

        // Hash codes should differ when snapshot info differs
        assertNotEquals("Hash codes should differ when snapshot info differs", hash1, hash2);

        // Equal objects should have equal hash codes
        Version v3 = new Version(1, 2, 3, "alpha", "com.example", "artifact");
        assertEquals("Equal objects should have equal hash codes", v1.hashCode(), v3.hashCode());
    }

    @Test
    public void testEqualsIncludesSnapshotInfo() {
        Version v1 = new Version(1, 2, 3, "alpha", "com.example", "artifact");
        Version v2 = new Version(1, 2, 3, "beta", "com.example", "artifact");

        // Versions with different snapshot info should not be equal
        assertFalse("Versions with different snapshot info should not be equal", v1.equals(v2));

        // Versions with same snapshot info should be equal
        Version v3 = new Version(1, 2, 3, "alpha", "com.example", "artifact");
        assertTrue("Versions with same snapshot info should be equal", v1.equals(v3));
    }

    @Test
    public void testCompareToIncludesSnapshotInfo() {
        // Test 1: Both snapshots - compare lexicographically
        Version v1 = new Version(1, 0, 0, "alpha", "com.example", "artifact");
        Version v2 = new Version(1, 0, 0, "beta", "com.example", "artifact");
        assertTrue("alpha should be less than beta", v1.compareTo(v2) < 0);
        assertTrue("beta should be greater than alpha", v2.compareTo(v1) > 0);

        // Test 2: Snapshot vs non-snapshot (empty string)
        Version v3 = new Version(1, 0, 0, "alpha", "com.example", "artifact");
        Version v4 = new Version(1, 0, 0, "", "com.example", "artifact");
        assertTrue("snapshot should be less than release", v3.compareTo(v4) < 0);
        assertTrue("release should be greater than snapshot", v4.compareTo(v3) > 0);

        // Test 3: Non-snapshot vs snapshot
        Version v5 = new Version(1, 0, 0, "", "com.example", "artifact");
        Version v6 = new Version(1, 0, 0, "alpha", "com.example", "artifact");
        assertTrue("release should be greater than snapshot", v5.compareTo(v6) > 0);
        assertTrue("snapshot should be less than release", v6.compareTo(v5) < 0);

        // Test 4: Both non-snapshots
        Version v7 = new Version(1, 0, 0, "", "com.example", "artifact");
        Version v8 = new Version(1, 0, 0, "", "com.example", "artifact");
        assertEquals("Both non-snapshots should be equal", 0, v7.compareTo(v8));

        // Test 5: Different group IDs take precedence
        Version v9 = new Version(1, 0, 0, "alpha", "com.example.a", "artifact");
        Version v10 = new Version(1, 0, 0, "beta", "com.example.b", "artifact");
        assertTrue("Group ID comparison should take precedence", v9.compareTo(v10) < 0);
    }

    @Test
    public void testHashCodeWithEmptySnapshotInfo() {
        // Test empty vs non-empty snapshot info
        Version v1 = new Version(1, 2, 3, "", "com.example", "artifact");
        Version v2 = new Version(1, 2, 3, "SNAPSHOT", "com.example", "artifact");
        assertNotEquals("Hash codes should differ when snapshot info differs", 
                        v1.hashCode(), v2.hashCode());

        // Test identical empty snapshot info
        Version v3 = new Version(1, 2, 3, "", "com.example", "artifact");
        assertEquals("Versions with same snapshot info should have same hash code", 
                     v1.hashCode(), v3.hashCode());
    }

    @Test
    public void testConsistencyBetweenEqualsAndCompareTo() {
        // Equal versions
        Version v1 = new Version(1, 2, 3, "alpha", "com.example", "artifact");
        Version v2 = new Version(1, 2, 3, "alpha", "com.example", "artifact");
        assertEquals("compareTo should return 0 for equal versions", 0, v1.compareTo(v2));
        assertTrue("equals should return true when compareTo returns 0", v1.equals(v2));

        // Different versions
        Version v3 = new Version(1, 2, 3, "alpha", "com.example", "artifact");
        Version v4 = new Version(1, 2, 3, "beta", "com.example", "artifact");
        assertNotEquals("compareTo should not return 0 for different versions", 0, v3.compareTo(v4));
        assertFalse("equals should return false when compareTo returns non-zero", v3.equals(v4));
    }
}

