    @Test
    public void testEqualsWithNullSnapshotInfoNoNPE() {
        // Scenario 1: Both versions have null snapshot info
        Version v1 = new Version(2, 16, 0, null, "com.fasterxml.jackson.core", "jackson-core");
        Version v2 = new Version(2, 16, 0, null, "com.fasterxml.jackson.core", "jackson-core");
        assertTrue("Versions with null snapshot should be equal", v1.equals(v2));

        // Scenario 2: First version null snapshot, second non-null
        Version v3 = new Version(2, 16, 0, null, "com.fasterxml.jackson.core", "jackson-core");
        Version v4 = new Version(2, 16, 0, "SNAPSHOT", "com.fasterxml.jackson.core", "jackson-core");
        assertFalse("Null vs non-null snapshot should be unequal", v3.equals(v4));

        // Scenario 3: First version non-null snapshot, second null
        Version v5 = new Version(2, 16, 0, "SNAPSHOT", "com.fasterxml.jackson.core", "jackson-core");
        Version v6 = new Version(2, 16, 0, null, "com.fasterxml.jackson.core", "jackson-core");
        assertFalse("Non-null vs null snapshot should be unequal", v5.equals(v6));

        // Scenario 4: Compare with unknown version (has null fields)
        Version unknown = Version.unknownVersion();
        assertFalse("Should not equal unknown version", v1.equals(unknown));
    }

    // Additional test for hash code consistency with null snapshot
    @Test
    public void testHashCodeWithNullSnapshot() {
        Version v1 = new Version(2, 16, 0, null, "com.fasterxml.jackson.core", "jackson-core");
        Version v2 = new Version(2, 16, 0, null, "com.fasterxml.jackson.core", "jackson-core");
        assertEquals("Equal versions must have equal hash codes", v1.hashCode(), v2.hashCode());
    }
}

