    @Test
    public void testNonBlockingByteArrayParserRespectsCanonicalizeFieldNames() throws IOException {
        // Test with CANONICALIZE_FIELD_NAMES disabled
        JsonFactory factoryDisabled = JsonFactory.builder()
                .disable(JsonFactory.Feature.CANONICALIZE_FIELD_NAMES)
                .build();

        // Test with CANONICALIZE_FIELD_NAMES enabled
        JsonFactory factoryEnabled = JsonFactory.builder()
                .enable(JsonFactory.Feature.CANONICALIZE_FIELD_NAMES)
                .build();

        // Same JSON input with repeated field names
        byte[] json = "{\"field1\":1,\"field1\":2}".getBytes("UTF-8");

        // Test with disabled canonicalization
        JsonParser parserDisabled = factoryDisabled.createNonBlockingByteArrayParser();
        ((NonBlockingJsonParser) parserDisabled).feedInput(json, 0, json.length);

        parserDisabled.nextToken(); // START_OBJECT
        parserDisabled.nextToken(); // FIELD_NAME "field1"
        String field1Disabled = parserDisabled.getCurrentName();
        parserDisabled.nextToken(); // VALUE_NUMBER_INT 1
        parserDisabled.nextToken(); // FIELD_NAME "field1" again
        String field2Disabled = parserDisabled.getCurrentName();

        // With canonicalization disabled, field names should be separate String instances
        assertNotSame("Field names should be different objects when canonicalization is disabled",
                   field1Disabled, field2Disabled);
        // Also, they should be equal in content
        assertEquals(field1Disabled, field2Disabled);

        // Test with enabled canonicalization
        JsonParser parserEnabled = factoryEnabled.createNonBlockingByteArrayParser();
        ((NonBlockingJsonParser) parserEnabled).feedInput(json, 0, json.length);

        parserEnabled.nextToken(); // START_OBJECT
        parserEnabled.nextToken(); // FIELD_NAME "field1"
        String field1Enabled = parserEnabled.getCurrentName();
        parserEnabled.nextToken(); // VALUE_NUMBER_INT 1
        parserEnabled.nextToken(); // FIELD_NAME "field1" again
        String field2Enabled = parserEnabled.getCurrentName();

        // With canonicalization enabled, field names should be the same String instance
        assertSame("Field names should be the same object when canonicalization is enabled",
                   field1Enabled, field2Enabled);

        parserDisabled.close();
        parserEnabled.close();
    }

