package com.fasterxml.jackson.core;

import com.fasterxml.jackson.core.json.async.NonBlockingJsonParser;
import org.junit.Test;

import java.io.IOException;

import static org.junit.Assert.*;

public class JsonFactoryCanonicalizationTest {

    @Test
    public void testNonBlockingByteArrayParserCanonicalization() throws IOException {
        // Test with canonicalization disabled
        JsonFactory factoryDisabled = new JsonFactory();
        factoryDisabled.disable(JsonFactory.Feature.CANONICALIZE_FIELD_NAMES);

        String json = "{\"field\":1,\"field\":2}";
        byte[] jsonBytes = json.getBytes("UTF-8");

        JsonParser parserDisabled = factoryDisabled.createNonBlockingByteArrayParser();
        ((NonBlockingJsonParser) parserDisabled).feedInput(jsonBytes, 0, jsonBytes.length);

        // Parse first field
        assertEquals(JsonToken.START_OBJECT, parserDisabled.nextToken());
        assertEquals(JsonToken.FIELD_NAME, parserDisabled.nextToken());
        String fieldName1Disabled = parserDisabled.getCurrentName();
        assertEquals(JsonToken.VALUE_NUMBER_INT, parserDisabled.nextToken());
        assertEquals(1, parserDisabled.getIntValue());

        // Parse second field
        assertEquals(JsonToken.FIELD_NAME, parserDisabled.nextToken());
        String fieldName2Disabled = parserDisabled.getCurrentName();
        assertEquals(JsonToken.VALUE_NUMBER_INT, parserDisabled.nextToken());
        assertEquals(2, parserDisabled.getIntValue());
        assertEquals(JsonToken.END_OBJECT, parserDisabled.nextToken());

        // Verify different objects when canonicalization disabled
        assertEquals("field", fieldName1Disabled);
        assertEquals("field", fieldName2Disabled);
        assertNotSame(fieldName1Disabled, fieldName2Disabled);

        parserDisabled.close();

        // Test with canonicalization enabled
        JsonFactory factoryEnabled = new JsonFactory();
        factoryEnabled.enable(JsonFactory.Feature.CANONICALIZE_FIELD_NAMES);

        JsonParser parserEnabled = factoryEnabled.createNonBlockingByteArrayParser();
        ((NonBlockingJsonParser) parserEnabled).feedInput(jsonBytes, 0, jsonBytes.length);

        // Parse first field
        assertEquals(JsonToken.START_OBJECT, parserEnabled.nextToken());
        assertEquals(JsonToken.FIELD_NAME, parserEnabled.nextToken());
        String fieldName1Enabled = parserEnabled.getCurrentName();
        assertEquals(JsonToken.VALUE_NUMBER_INT, parserEnabled.nextToken());
        assertEquals(1, parserEnabled.getIntValue());

        // Parse second field
        assertEquals(JsonToken.FIELD_NAME, parserEnabled.nextToken());
        String fieldName2Enabled = parserEnabled.getCurrentName();
        assertEquals(JsonToken.VALUE_NUMBER_INT, parserEnabled.nextToken());
        assertEquals(2, parserEnabled.getIntValue());
        assertEquals(JsonToken.END_OBJECT, parserEnabled.nextToken());

        // Verify same object when canonicalization enabled
        assertEquals("field", fieldName1Enabled);
        assertEquals("field", fieldName2Enabled);
        assertSame(fieldName1Enabled, fieldName2Enabled);

        parserEnabled.close();
    }
}

