package com.fasterxml.jackson.core;

import org.junit.Test;
import static org.junit.Assert.*;

public class VersionTest {

    @Test
    public void testCompareToWithSnapshotInfo() {
        // Test case 1: Both versions are snapshots, different snapshot info
        Version v1 = new Version(1, 0, 0, "alpha", "com.example", "artifact");
        Version v2 = new Version(1, 0, 0, "beta", "com.example", "artifact");

        // After patch: should return negative (alpha < beta)
        assertTrue("Snapshot alpha should be less than beta", v1.compareTo(v2) < 0);
        assertTrue("Snapshot beta should be greater than alpha", v2.compareTo(v1) > 0);

        // Test case 2: One snapshot, one release (same version numbers)
        Version v3 = new Version(1, 0, 0, "alpha", "com.example", "artifact");
        Version v4 = new Version(1, 0, 0, "", "com.example", "artifact");

        // After patch: snapshot should be less than release
        assertTrue("Snapshot should be less than release", v3.compareTo(v4) < 0);
        assertTrue("Release should be greater than snapshot", v4.compareTo(v3) > 0);

        // Test case 3: Both releases (no snapshot info)
        Version v5 = new Version(1, 0, 0, "", "com.example", "artifact");
        Version v6 = new Version(1, 0, 0, "", "com.example", "artifact");

        // Should be equal regardless of patch
        assertEquals("Two releases should be equal", 0, v5.compareTo(v6));

        // Test case 4: Same snapshot info
        Version v7 = new Version(1, 0, 0, "alpha", "com.example", "artifact");
        Version v8 = new Version(1, 0, 0, "alpha", "com.example", "artifact");

        // Should be equal regardless of patch
        assertEquals("Same snapshot info should be equal", 0, v7.compareTo(v8));
    }

    @Test
    public void testEqualsWithSnapshotInfo() {
        // Test that equals considers snapshot info
        Version v1 = new Version(1, 0, 0, "alpha", "com.example", "artifact");
        Version v2 = new Version(1, 0, 0, "beta", "com.example", "artifact");
        Version v3 = new Version(1, 0, 0, "alpha", "com.example", "artifact");
        Version v4 = new Version(1, 0, 0, "", "com.example", "artifact");
        Version v5 = new Version(1, 0, 0, "", "com.example", "artifact");

        // After patch: should return false
        assertFalse("Different snapshot info should not be equal", v1.equals(v2));

        // Same snapshot info should be equal
        assertTrue("Same snapshot info should be equal", v1.equals(v3));

        // Snapshot vs release should not be equal
        assertFalse("Snapshot should not equal release", v1.equals(v4));
        assertFalse("Release should not equal snapshot", v4.equals(v1));

        // Both releases should be equal
        assertTrue("Both releases should be equal", v4.equals(v5));
    }

    @Test
    public void testHashCodeWithSnapshotInfo() {
        // Test that hashCode includes snapshot info
        Version v1 = new Version(1, 0, 0, "alpha", "com.example", "artifact");
        Version v2 = new Version(1, 0, 0, "beta", "com.example", "artifact");
        Version v3 = new Version(1, 0, 0, "alpha", "com.example", "artifact");

        // After patch: should be different
        assertNotEquals("Different snapshot info should have different hash codes", 
                       v1.hashCode(), v2.hashCode());

        // Same snapshot info should have same hash code
        assertEquals("Same snapshot info should have same hash code", 
                    v1.hashCode(), v3.hashCode());

        // Test snapshot vs release
        Version v4 = new Version(1, 0, 0, "", "com.example", "artifact");
        assertNotEquals("Snapshot and release should have different hash codes", 
                       v1.hashCode(), v4.hashCode());
    }

    @Test
    public void testCompareToHierarchy() {
        // Ensure the hierarchy still works correctly
        // Different groupId
        Version v1 = new Version(1, 0, 0, "", "com.example1", "artifact");
        Version v2 = new Version(1, 0, 0, "", "com.example2", "artifact");
        assertTrue("Different groupId should be compared", v1.compareTo(v2) != 0);

        // Different artifactId
        Version v3 = new Version(1, 0, 0, "", "com.example", "artifact1");
        Version v4 = new Version(1, 0, 0, "", "com.example", "artifact2");
        assertTrue("Different artifactId should be compared", v3.compareTo(v4) != 0);

        // Different major version
        Version v5 = new Version(1, 0, 0, "", "com.example", "artifact");
        Version v6 = new Version(2, 0, 0, "", "com.example", "artifact");
        assertTrue("Different major version should be compared", v5.compareTo(v6) < 0);

        // Different minor version
        Version v7 = new Version(1, 1, 0, "", "com.example", "artifact");
        Version v8 = new Version(1, 2, 0, "", "com.example", "artifact");
        assertTrue("Different minor version should be compared", v7.compareTo(v8) < 0);

        // Different patch level
        Version v9 = new Version(1, 0, 1, "", "com.example", "artifact");
        Version v10 = new Version(1, 0, 2, "", "com.example", "artifact");
        assertTrue("Different patch level should be compared", v9.compareTo(v10) < 0);
    }

    @Test
    public void testCompareToSnapshotEdgeCases() {
        // Test with empty string snapshot info (should be considered non-snapshot)
        Version v1 = new Version(1, 0, 0, "", "com.example", "artifact");
        Version v2 = new Version(1, 0, 0, "", "com.example", "artifact");

        // Both should be considered non-snapshots -> equal
        assertEquals("Empty string snapshot should equal empty string snapshot", 0, v1.compareTo(v2));
        assertTrue("Empty string snapshot should equal empty string snapshot", v1.equals(v2));

        // Test with same version but one has empty snapshot string -> same as above, already covered?

        // Test snapshot ordering with different strings
        Version v5 = new Version(1, 0, 0, "alpha.1", "com.example", "artifact");
        Version v6 = new Version(1, 0, 0, "alpha.2", "com.example", "artifact");
        assertTrue("alpha.1 should be less than alpha.2", v5.compareTo(v6) < 0);
    }

    @Test
    public void testCompareToWithNonEmptySnapshotVsEmpty() {
        // Create versions with same group/artifact/version numbers
        Version snapshotVersion = new Version(1, 0, 0, "SNAPSHOT", "com.example", "artifact");
        Version emptySnapshotVersion = new Version(1, 0, 0, "", "com.example", "artifact");

        // Non-empty snapshot should be treated as snapshot
        // Empty snapshot should be treated as release
        // Snapshot should be less than release
        assertTrue("Snapshot version should be less than empty-snapshot version", 
                  snapshotVersion.compareTo(emptySnapshotVersion) < 0);
        assertTrue("Empty-snapshot version should be greater than snapshot version", 
                  emptySnapshotVersion.compareTo(snapshotVersion) > 0);
    }

    @Test
    public void testCompareToSnapshotOnlyWhenVersionsEqual() {
        // Different major version: higher major dominates regardless of snapshot
        Version v1 = new Version(2, 0, 0, "alpha", "com.example", "artifact");
        Version v2 = new Version(1, 0, 0, "", "com.example", "artifact");
        assertTrue("Higher major version should be greater despite snapshot", v1.compareTo(v2) > 0);

        // Different minor version: higher minor dominates
        Version v3 = new Version(1, 1, 0, "alpha", "com.example", "artifact");
        Version v4 = new Version(1, 0, 0, "", "com.example", "artifact");
        assertTrue("Higher minor version should be greater despite snapshot", v3.compareTo(v4) > 0);

        // Different patch level: higher patch dominates
        Version v5 = new Version(1, 0, 1, "alpha", "com.example", "artifact");
        Version v6 = new Version(1, 0, 0, "", "com.example", "artifact");
        assertTrue("Higher patch level should be greater despite snapshot", v5.compareTo(v6) > 0);

        // Different groupId: comparison based on groupId, ignoring snapshot
        Version v7 = new Version(1, 0, 0, "alpha", "com.example1", "artifact");
        Version v8 = new Version(1, 0, 0, "", "com.example2", "artifact");
        assertTrue("Different groupIds should not compare as equal", v7.compareTo(v8) != 0);

        // Different artifactId: comparison based on artifactId, ignoring snapshot
        Version v9 = new Version(1, 0, 0, "alpha", "com.example", "artifact1");
        Version v10 = new Version(1, 0, 0, "", "com.example", "artifact2");
        assertTrue("Different artifactIds should not compare as equal", v9.compareTo(v10) != 0);

        // Same version components: snapshot info should determine order
        Version v11 = new Version(1, 0, 0, "alpha", "com.example", "artifact");
        Version v12 = new Version(1, 0, 0, "", "com.example", "artifact");
        assertTrue("Snapshot should be less than release when versions are equal", v11.compareTo(v12) < 0);
        assertTrue("Release should be greater than snapshot when versions are equal", v12.compareTo(v11) > 0);
    }
}

