            parser.readBinaryValue(variant, new ByteArrayOutputStream());
            fail("Expected exception for missing padding when required");
        } catch (Exception e) {
            assertNotNull(e);
        }
    }

    @Test
    public void testReadBinaryThreeCharsWithPaddingAllowed() throws IOException {
        String json = "\"AAA\"";
