    @Test
    public void testReadBinaryThreeCharsWithPaddingRequired() throws IOException {
        String json = "\"AAA\"";
        Base64Variant variant = Base64Variants.MIME_NO_LINEFEEDS; // Default requires padding

        try (ReaderBasedJsonParser parser = createParser(json)) {
            assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
            parser.readBinaryValue(variant, new ByteArrayOutputStream());
            fail("Expected exception for missing padding when required");
        } catch (Exception e) {
            assertNotNull(e);
        }
    }

    @Test
    public void testUrlVariantWithoutPadding() throws IOException {
        String json = "\"AA\""; // URL variant never uses padding
        Base64Variant variant = Base64Variants.MODIFIED_FOR_URL;

        try (ReaderBasedJsonParser parser = createParser(json)) {
            assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
            byte[] result = parser.getBinaryValue(variant);
            assertArrayEquals(new byte[]{0}, result);
        }
    }

    @Test
    public void testInvalidPaddingCharAfterTwoBase64Chars() throws IOException {
        String json = "\"A=X\""; // Invalid padding after two base64 chars
        Base64Variant variant = Base64Variants.MIME_NO_LINEFEEDS; // Requires padding

        try (ReaderBasedJsonParser parser = createParser(json)) {
            assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
            parser.getBinaryValue(variant);
            fail("Expected exception for invalid padding char");
        } catch (Exception e) {
            assertNotNull(e);
        }
    }
