package com.fasterxml.jackson.core;

import com.fasterxml.jackson.core.json.UTF8DataInputJsonParser;
import com.fasterxml.jackson.core.json.async.NonBlockingByteBufferJsonParser;
import com.fasterxml.jackson.core.json.async.NonBlockingJsonParser;
import com.fasterxml.jackson.core.sym.ByteQuadsCanonicalizer;
import org.junit.Test;

import java.io.ByteArrayInputStream;
import java.io.DataInput;
import java.io.DataInputStream;
import java.io.IOException;
import java.lang.reflect.Field;
import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;

import static org.junit.Assert.*;

public class JsonFactoryCanonicalizationTest {

    // Helper method to access parser's symbol table via reflection with hierarchy traversal
    private ByteQuadsCanonicalizer getSymbols(JsonParser parser) throws Exception {
        Class<?> clazz = parser.getClass();
        while (clazz != null) {
            try {
                Field symbolsField = clazz.getDeclaredField("_symbols");
                symbolsField.setAccessible(true);
                return (ByteQuadsCanonicalizer) symbolsField.get(parser);
            } catch (NoSuchFieldException e) {
                clazz = clazz.getSuperclass();
            }
        }
        throw new NoSuchFieldException("_symbols");
    }

    // Functional interface for parser creation
    @FunctionalInterface
    private interface ParserCreator {
        JsonParser create(JsonFactory factory) throws IOException;
    }

    // Helper method to test canonicalization setting for a parser type
    private void testCanonicalizationForParserType(ParserCreator parserCreator) throws Exception {
        // Test with canonicalization DISABLED
        JsonFactory factoryDisabled = JsonFactory.builder()
                .disable(JsonFactory.Feature.CANONICALIZE_FIELD_NAMES)
                .build();

        JsonParser parserDisabled = parserCreator.create(factoryDisabled);
        ByteQuadsCanonicalizer symbolsDisabled = getSymbols(parserDisabled);
        assertFalse("Canonicalization should be disabled", symbolsDisabled.isCanonicalizing());

        // Feed data to non-blocking parsers
        if (parserDisabled instanceof NonBlockingJsonParser) {
            byte[] data = "{\"field1\":1,\"field2\":2}".getBytes(StandardCharsets.UTF_8);
            ((NonBlockingJsonParser) parserDisabled).feedInput(data, 0, data.length);
            ((NonBlockingJsonParser) parserDisabled).endOfInput();
        } else if (parserDisabled instanceof NonBlockingByteBufferJsonParser) {
            byte[] data = "{\"field1\":1,\"field2\":2}".getBytes(StandardCharsets.UTF_8);
            ByteBuffer buf = ByteBuffer.wrap(data);
            ((NonBlockingByteBufferJsonParser) parserDisabled).feedInput(buf);
            ((NonBlockingByteBufferJsonParser) parserDisabled).endOfInput();
        }

        // Parse tokens and validate
        assertEquals(JsonToken.START_OBJECT, parserDisabled.nextToken());
        assertEquals(JsonToken.FIELD_NAME, parserDisabled.nextToken());
        assertEquals("field1", parserDisabled.getCurrentName());
        assertEquals(JsonToken.VALUE_NUMBER_INT, parserDisabled.nextToken());
        assertEquals(JsonToken.FIELD_NAME, parserDisabled.nextToken());
        assertEquals("field2", parserDisabled.getCurrentName());
        assertEquals("Symbol table should be placeholder when canonicalization disabled", 
                     -1, symbolsDisabled.size());

        parserDisabled.close();

        // Test with canonicalization ENABLED
        JsonFactory factoryEnabled = JsonFactory.builder()
                .enable(JsonFactory.Feature.CANONICALIZE_FIELD_NAMES)
                .build();

        JsonParser parserEnabled = parserCreator.create(factoryEnabled);
        ByteQuadsCanonicalizer symbolsEnabled = getSymbols(parserEnabled);
        assertTrue("Canonicalization should be enabled", symbolsEnabled.isCanonicalizing());

        // Feed data to non-blocking parsers
        if (parserEnabled instanceof NonBlockingJsonParser) {
            byte[] data = "{\"field1\":1,\"field2\":2}".getBytes(StandardCharsets.UTF_8);
            ((NonBlockingJsonParser) parserEnabled).feedInput(data, 0, data.length);
            ((NonBlockingJsonParser) parserEnabled).endOfInput();
        } else if (parserEnabled instanceof NonBlockingByteBufferJsonParser) {
            byte[] data = "{\"field1\":1,\"field2\":2}".getBytes(StandardCharsets.UTF_8);
            ByteBuffer buf = ByteBuffer.wrap(data);
            ((NonBlockingByteBufferJsonParser) parserEnabled).feedInput(buf);
            ((NonBlockingByteBufferJsonParser) parserEnabled).endOfInput();
        }

        // Parse tokens and validate
        assertEquals(JsonToken.START_OBJECT, parserEnabled.nextToken());
        assertEquals(JsonToken.FIELD_NAME, parserEnabled.nextToken());
        assertEquals("field1", parserEnabled.getCurrentName());
        assertEquals(JsonToken.VALUE_NUMBER_INT, parserEnabled.nextToken());
        assertEquals(JsonToken.FIELD_NAME, parserEnabled.nextToken());
        assertEquals("field2", parserEnabled.getCurrentName());
        assertTrue("Symbol table should contain entries when canonicalization enabled", 
                   symbolsEnabled.size() > 0);

        parserEnabled.close();
    }

    // Test DataInput parser
    @Test
    public void testDataInputParserCanonicalization() throws Exception {
        testCanonicalizationForParserType(factory -> {
            byte[] jsonBytes = "{\"field1\":1,\"field2\":2}".getBytes(StandardCharsets.UTF_8);
            ByteArrayInputStream bais = new ByteArrayInputStream(jsonBytes);
            DataInput dataInput = new DataInputStream(bais);
            return factory.createParser(dataInput);
        });
    }

    // Test non-blocking byte array parser
    @Test
    public void testNonBlockingByteArrayParserCanonicalization() throws Exception {
        testCanonicalizationForParserType(JsonFactory::createNonBlockingByteArrayParser);
    }

    // Test non-blocking byte buffer parser
    @Test
    public void testNonBlockingByteBufferParserCanonicalization() throws Exception {
        testCanonicalizationForParserType(JsonFactory::createNonBlockingByteBufferParser);
    }

    // Test UTF-8 BOM handling in DataInput parser
    @Test
    public void testDataInputWithBOM() throws Exception {
        JsonFactory factory = JsonFactory.builder()
                .enable(JsonFactory.Feature.CANONICALIZE_FIELD_NAMES)
                .build();

        // Create JSON with UTF-8 BOM
        byte[] bom = {(byte) 0xEF, (byte) 0xBB, (byte) 0xBF};
        byte[] jsonBytes = "{\"field\":\"value\"}".getBytes(StandardCharsets.UTF_8);
        byte[] dataWithBom = new byte[bom.length + jsonBytes.length];
        System.arraycopy(bom, 0, dataWithBom, 0, bom.length);
        System.arraycopy(jsonBytes, 0, dataWithBom, bom.length, jsonBytes.length);

        ByteArrayInputStream bais = new ByteArrayInputStream(dataWithBom);
        DataInput dataInput = new DataInputStream(bais);

        try (JsonParser parser = factory.createParser(dataInput)) {
            ByteQuadsCanonicalizer symbols = getSymbols(parser);
            assertTrue(symbols.isCanonicalizing());

            assertEquals(JsonToken.START_OBJECT, parser.nextToken());
            assertEquals(JsonToken.FIELD_NAME, parser.nextToken());
            assertEquals("field", parser.getCurrentName());
            assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
            assertEquals("value", parser.getText());
            assertEquals(JsonToken.END_OBJECT, parser.nextToken());
            assertNull(parser.nextToken());

            assertTrue("Symbol table should contain entries", symbols.size() > 0);
        }
    }
}

