package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.sym.ByteQuadsCanonicalizer;
import com.fasterxml.jackson.core.json.async.NonBlockingJsonParser;
import com.fasterxml.jackson.core.json.async.NonBlockingJsonParserBase;
import com.fasterxml.jackson.core.json.async.NonBlockingByteBufferJsonParser;
import org.junit.Test;

import java.io.*;
import java.lang.reflect.Field;
import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;

import static org.junit.Assert.*;

public class UTF8DataInputJsonParserCanonicalizationTest {

    private JsonFactory createFactoryWithoutCanonicalization() {
        return JsonFactory.builder()
                .disable(JsonFactory.Feature.CANONICALIZE_FIELD_NAMES)
                .build();
    }

    private JsonFactory createFactoryWithCanonicalization() {
        return JsonFactory.builder()
                .enable(JsonFactory.Feature.CANONICALIZE_FIELD_NAMES)
                .build();
    }

    @Test
    public void testDataInputParserWithoutCanonicalization() throws Exception {
        JsonFactory factory = createFactoryWithoutCanonicalization();
        testDataInputParser(factory, "testField", false);
        testDataInputParser(factory, "testFieldWithÜnicode", false);
        testDataInputParser(factory, "test\u0800Field", false); // 3-byte char
        testDataInputParser(factory, "test\uD83D\uDE00Field", false); // 4-byte char (emoji)
    }

    @Test
    public void testDataInputParserWithCanonicalization() throws Exception {
        JsonFactory factory = createFactoryWithCanonicalization();
        testDataInputParser(factory, "testField", true);
        testDataInputParser(factory, "testFieldWithÜnicode", true);
        testDataInputParser(factory, "test\u0800Field", true); // 3-byte char
        testDataInputParser(factory, "test\uD83D\uDE00Field", true); // 4-byte char (emoji)
    }

    private void testDataInputParser(JsonFactory factory, String fieldName, boolean expectCanonicalizing) throws Exception {
        String json = "{\"" + fieldName + "\":\"value\"}";
        DataInput dataInput = new ByteArrayDataInput(json.getBytes(StandardCharsets.UTF_8));

        try (JsonParser parser = factory.createParser(dataInput)) {
            parser.nextToken(); // START_OBJECT
            parser.nextToken(); // FIELD_NAME
            assertEquals(fieldName, parser.getCurrentName());

            ByteQuadsCanonicalizer symbols = getSymbols(parser);
            assertEquals(expectCanonicalizing, symbols.isCanonicalizing());
        }
    }

    @Test
    public void testNonBlockingByteArrayParserWithoutCanonicalization() throws Exception {
        JsonFactory factory = createFactoryWithoutCanonicalization();
        testNonBlockingByteArrayParser(factory, "testField", false);
        testNonBlockingByteArrayParser(factory, "testFieldWithÜnicode", false);
        testNonBlockingByteArrayParser(factory, "test\u0800Field", false); // 3-byte char
        testNonBlockingByteArrayParser(factory, "test\uD83D\uDE00Field", false); // 4-byte char (emoji)
    }

    @Test
    public void testNonBlockingByteArrayParserWithCanonicalization() throws Exception {
        JsonFactory factory = createFactoryWithCanonicalization();
        testNonBlockingByteArrayParser(factory, "testField", true);
        testNonBlockingByteArrayParser(factory, "testFieldWithÜnicode", true);
        testNonBlockingByteArrayParser(factory, "test\u0800Field", true); // 3-byte char
        testNonBlockingByteArrayParser(factory, "test\uD83D\uDE00Field", true); // 4-byte char (emoji)
    }

    private void testNonBlockingByteArrayParser(JsonFactory factory, String fieldName, boolean expectCanonicalizing) throws Exception {
        String json = "{\"" + fieldName + "\":\"value\"}";
        byte[] jsonBytes = json.getBytes(StandardCharsets.UTF_8);

        try (NonBlockingJsonParser parser = (NonBlockingJsonParser) factory.createNonBlockingByteArrayParser()) {
            parser.feedInput(jsonBytes, 0, jsonBytes.length);
            parser.endOfInput();

            assertEquals(JsonToken.START_OBJECT, parser.nextToken());
            assertEquals(JsonToken.FIELD_NAME, parser.nextToken());
            assertEquals(fieldName, parser.getCurrentName());

            ByteQuadsCanonicalizer symbols = getSymbols(parser);
            assertEquals(expectCanonicalizing, symbols.isCanonicalizing());
        }
    }

    @Test
    public void testNonBlockingByteBufferParserWithoutCanonicalization() throws Exception {
        JsonFactory factory = createFactoryWithoutCanonicalization();
        testNonBlockingByteBufferParser(factory, "testField", false);
        testNonBlockingByteBufferParser(factory, "testFieldWithÜnicode", false);
        testNonBlockingByteBufferParser(factory, "test\u0800Field", false); // 3-byte char
        testNonBlockingByteBufferParser(factory, "test\uD83D\uDE00Field", false); // 4-byte char (emoji)
    }

    @Test
    public void testNonBlockingByteBufferParserWithCanonicalization() throws Exception {
        JsonFactory factory = createFactoryWithCanonicalization();
        testNonBlockingByteBufferParser(factory, "testField", true);
        testNonBlockingByteBufferParser(factory, "testFieldWithÜnicode", true);
        testNonBlockingByteBufferParser(factory, "test\u0800Field", true); // 3-byte char
        testNonBlockingByteBufferParser(factory, "test\uD83D\uDE00Field", true); // 4-byte char (emoji)
    }

    private void testNonBlockingByteBufferParser(JsonFactory factory, String fieldName, boolean expectCanonicalizing) throws Exception {
        String json = "{\"" + fieldName + "\":\"value\"}";
        byte[] jsonBytes = json.getBytes(StandardCharsets.UTF_8);
        ByteBuffer buf = ByteBuffer.wrap(jsonBytes);

        try (NonBlockingByteBufferJsonParser parser = (NonBlockingByteBufferJsonParser) factory.createNonBlockingByteBufferParser()) {
            parser.feedInput(buf);
            parser.endOfInput();

            assertEquals(JsonToken.START_OBJECT, parser.nextToken());
            assertEquals(JsonToken.FIELD_NAME, parser.nextToken());
