            {ParserType.DATA_INPUT, "getBinaryValue"},
            {ParserType.DATA_INPUT, "readBinaryValue"},
            {ParserType.INPUT_STREAM, "getBinaryValue"},
            {ParserType.INPUT_STREAM, "readBinaryValue"},
            {ParserType.READER, "getBinaryValue"},
            {ParserType.READER, "readBinaryValue"}
        });
    }

    private final ParserType parserType;
    private final boolean useReadBinaryValue;

