        if (useReadBinaryValue) {
            ByteArrayOutputStream out = new ByteArrayOutputStream();
            parser.readBinaryValue(variant, out);
            return out.toByteArray();
        } else {
            return parser.getBinaryValue(variant);
        }
    }

    private JsonParser createParser(JsonFactory factory, byte[] jsonBytes) throws IOException {
        switch (parserType) {
        case DATA_INPUT:
            DataInput dataInput = new DataInputStream(new ByteArrayInputStream(jsonBytes));
            return factory.createParser(dataInput);
