package com.fasterxml.jackson.core.io;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

/**
 * Unit tests for {@link NumberInput#looksLikeValidNumber(String)} focusing on
 * the fix for trailing dot validation (issue #1308).
 */
class NumberInputLooksLikeValidNumberTest {

    @Test
    void testTrailingDotNumbers() {
        // Positive cases with trailing dot
        assertTrue(NumberInput.looksLikeValidNumber("3."));
        assertTrue(NumberInput.looksLikeValidNumber("+12."));
        assertTrue(NumberInput.looksLikeValidNumber("-5."));
        assertTrue(NumberInput.looksLikeValidNumber("123."));
        assertTrue(NumberInput.looksLikeValidNumber("0."));
        assertTrue(NumberInput.looksLikeValidNumber("+0."));
        assertTrue(NumberInput.looksLikeValidNumber("-0."));

        // Ensure multi-digit numbers with trailing dot work
        assertTrue(NumberInput.looksLikeValidNumber("9876543210."));
    }

    @Test
    void testOriginalPatternStillWorks() {
        // Integers
        assertTrue(NumberInput.looksLikeValidNumber("0"));
        assertTrue(NumberInput.looksLikeValidNumber("42"));
        assertTrue(NumberInput.looksLikeValidNumber("+100"));
        assertTrue(NumberInput.looksLikeValidNumber("-999"));

        // Decimals without trailing dot
        assertTrue(NumberInput.looksLikeValidNumber("3.14"));
        assertTrue(NumberInput.looksLikeValidNumber(".5"));
        assertTrue(NumberInput.looksLikeValidNumber("+0.25"));
        assertTrue(NumberInput.looksLikeValidNumber("-12.345"));

        // Scientific notation
        assertTrue(NumberInput.looksLikeValidNumber("1e10"));
        assertTrue(NumberInput.looksLikeValidNumber("2.5E-3"));
        assertTrue(NumberInput.looksLikeValidNumber("+6.02e23"));
        assertTrue(NumberInput.looksLikeValidNumber("-1.6E-19"));

        // Edge cases from original pattern
        assertTrue(NumberInput.looksLikeValidNumber("0.0"));
        assertTrue(NumberInput.looksLikeValidNumber("00.00")); // leading zeros allowed
    }

    @Test
    void testInvalidInputs() {
        // Null and empty
        assertFalse(NumberInput.looksLikeValidNumber(null));
        assertFalse(NumberInput.looksLikeValidNumber(""));

        // Single non-digit character
        assertFalse(NumberInput.looksLikeValidNumber("a"));
        assertFalse(NumberInput.looksLikeValidNumber("+"));
        assertFalse(NumberInput.looksLikeValidNumber("-"));
        assertFalse(NumberInput.looksLikeValidNumber("."));

        // Invalid trailing dot cases
        assertFalse(NumberInput.looksLikeValidNumber(".")); // just dot
        assertFalse(NumberInput.looksLikeValidNumber("+.")); // sign then dot
        assertFalse(NumberInput.looksLikeValidNumber("-.")); // negative sign then dot
        assertFalse(NumberInput.looksLikeValidNumber("..")); // double dot
        assertFalse(NumberInput.looksLikeValidNumber("3..")); // double dot after digits
        assertFalse(NumberInput.looksLikeValidNumber(".3.")); // dot before and after

        // Non-numeric strings
        assertFalse(NumberInput.looksLikeValidNumber("abc"));
        assertFalse(NumberInput.looksLikeValidNumber("12a"));
        assertFalse(NumberInput.looksLikeValidNumber("1.2.3"));
        assertFalse(NumberInput.looksLikeValidNumber("3.14a"));

        // Trailing dot with scientific notation (should not match trailing dot pattern)
        assertFalse(NumberInput.looksLikeValidNumber("1.e10"));
        assertFalse(NumberInput.looksLikeValidNumber("2.E-3"));
        assertFalse(NumberInput.looksLikeValidNumber("1.5e"));
        assertFalse(NumberInput.looksLikeValidNumber("1.5e+"));
    }

    @Test
    void testSingleDigit() {
        // Single digits should work
        assertTrue(NumberInput.looksLikeValidNumber("0"));
        assertTrue(NumberInput.looksLikeValidNumber("5"));
        assertTrue(NumberInput.looksLikeValidNumber("9"));

        // Single digit with trailing dot should also work
        assertTrue(NumberInput.looksLikeValidNumber("0."));
        assertTrue(NumberInput.looksLikeValidNumber("5."));
        assertTrue(NumberInput.looksLikeValidNumber("9."));
    }

    @Test
    void testBoundaryCases() {
        // Very long numbers with trailing dot
        assertTrue(NumberInput.looksLikeValidNumber("123456789012345678901234567890."));

        // Test that trailing whitespace (space, tab) or leading whitespace make the number invalid
        assertFalse(NumberInput.looksLikeValidNumber("3. ")); // trailing space
        assertFalse(NumberInput.looksLikeValidNumber("3.\t")); // trailing tab
        assertFalse(NumberInput.looksLikeValidNumber(" 3.")); // leading space
    }
}

